<span class="line"><span style="color:#E1E4E8;">                cursor </span><span style="color:#F97583;">=</span><span style="color:#E1E4E8;"> conn.cursor(</span><span style="color:#FFAB70;">dictionary</span><span style="color:#F97583;">=</span><span style="color:#79B8FF;">True</span><span style="color:#E1E4E8;">)</span></span>
